'use strict';
const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Reflect.ownKeys(api).sort(), ['addTicket', 'deleteTicket', 'initialState', 'ticketReducer', 'toggleTicket'].sort());
const { initialState, addTicket, toggleTicket, deleteTicket, ticketReducer } = api;

assert.deepStrictEqual(initialState, { nextId: 1, tickets: [] });
assert.ok(Object.isFrozen(initialState));
assert.ok(Object.isFrozen(initialState.tickets));
assert.deepStrictEqual(addTicket('Leak', 'Pipe 4'), { type: 'ticket/add', payload: { title: 'Leak', details: 'Pipe 4' } });
assert.deepStrictEqual(toggleTicket(7), { type: 'ticket/toggle', payload: { id: 7 } });
assert.deepStrictEqual(deleteTicket(7), { type: 'ticket/delete', payload: { id: 7 } });

assert.strictEqual(ticketReducer(undefined, { type: 'unknown' }), initialState);
assert.strictEqual(ticketReducer(initialState, null), initialState);
assert.strictEqual(ticketReducer(initialState, {}), initialState);

const addAction = addTicket('  Replace filter  ', 'North unit');
const s1 = ticketReducer(initialState, addAction);
assert.deepStrictEqual(s1, {
  nextId: 2,
  tickets: [{ id: 1, title: 'Replace filter', details: 'North unit', status: 'Open' }]
});
assert.notStrictEqual(s1, initialState);
assert.notStrictEqual(s1.tickets, initialState.tickets);
assert.deepStrictEqual(addAction, { type: 'ticket/add', payload: { title: '  Replace filter  ', details: 'North unit' } });

const firstTicket = s1.tickets[0];
const s2 = ticketReducer(s1, addTicket('Inspect pump', ''));
assert.strictEqual(s2.nextId, 3);
assert.strictEqual(s2.tickets[0], firstTicket);
assert.deepStrictEqual(s2.tickets[1], { id: 2, title: 'Inspect pump', details: '', status: 'Open' });

const s3 = ticketReducer(s2, toggleTicket(1));
assert.notStrictEqual(s3, s2);
assert.notStrictEqual(s3.tickets, s2.tickets);
assert.notStrictEqual(s3.tickets[0], s2.tickets[0]);
assert.strictEqual(s3.tickets[1], s2.tickets[1]);
assert.strictEqual(s3.tickets[0].status, 'Resolved');
assert.strictEqual(s2.tickets[0].status, 'Open');

const s4 = ticketReducer(s3, toggleTicket(1));
assert.strictEqual(s4.tickets[0].status, 'Open');
assert.strictEqual(s4.nextId, 3);
assert.strictEqual(ticketReducer(s4, toggleTicket(99)), s4);
assert.strictEqual(ticketReducer(s4, deleteTicket(99)), s4);

const retained = s4.tickets[1];
const s5 = ticketReducer(s4, deleteTicket(1));
assert.deepStrictEqual(s5, { nextId: 3, tickets: [retained] });
assert.notStrictEqual(s5.tickets, s4.tickets);
assert.strictEqual(s5.tickets[0], retained);
const s6 = ticketReducer(s5, addTicket('Third ID', 'IDs are not reused'));
assert.strictEqual(s6.tickets[1].id, 3);
assert.strictEqual(s6.nextId, 4);

for (const action of [
  { type: 'ticket/add', payload: { title: '', details: 'x' } },
  { type: 'ticket/add', payload: { title: '   ', details: 'x' } },
  { type: 'ticket/add', payload: { title: 'x', details: 1 } },
  { type: 'ticket/add' },
  { type: 'ticket/toggle', payload: { id: 0 } },
  { type: 'ticket/toggle', payload: { id: 1.5 } },
  { type: 'ticket/toggle', payload: { id: '1' } },
  { type: 'ticket/delete', payload: { id: -1 } },
  { type: 'ticket/delete' }
]) assert.throws(() => ticketReducer(s2, action), TypeError);

assert.deepStrictEqual(s2, {
  nextId: 3,
  tickets: [
    { id: 1, title: 'Replace filter', details: 'North unit', status: 'Open' },
    { id: 2, title: 'Inspect pump', details: '', status: 'Open' }
  ]
});

const externalTicket = { id: 4, status: 'Open' };
Object.defineProperties(externalTicket, {
  title: { value: 'Concealed title', enumerable: false },
  details: { value: 'Concealed details', enumerable: false }
});
Object.freeze(externalTicket);
const externalTickets = Object.freeze([externalTicket]);
const externalState = { tickets: externalTickets };
Object.defineProperty(externalState, 'nextId', { value: 5, enumerable: false });
Object.freeze(externalState);

const hiddenPayload = {};
Object.defineProperties(hiddenPayload, {
  title: { value: '  Hidden action  ', enumerable: false },
  details: { value: 'Hidden payload details', enumerable: false }
});
Object.freeze(hiddenPayload);
const hiddenAction = Object.freeze({ type: 'ticket/add', payload: hiddenPayload });
const externalAdded = ticketReducer(externalState, hiddenAction);
assert.strictEqual(externalAdded.nextId, 6);
assert.notStrictEqual(externalAdded, externalState);
assert.notStrictEqual(externalAdded.tickets, externalTickets);
assert.strictEqual(externalAdded.tickets[0], externalTicket);
assert.deepStrictEqual(externalAdded.tickets[1], {
  id: 5,
  title: 'Hidden action',
  details: 'Hidden payload details',
  status: 'Open'
});
assert.strictEqual(hiddenPayload.title, '  Hidden action  ');
assert.strictEqual(hiddenPayload.details, 'Hidden payload details');

const externalToggled = ticketReducer(externalState, toggleTicket(4));
assert.strictEqual(externalToggled.nextId, 5);
assert.notStrictEqual(externalToggled.tickets[0], externalTicket);
assert.strictEqual(externalToggled.tickets[0].id, 4);
assert.strictEqual(externalToggled.tickets[0].title, 'Concealed title');
assert.strictEqual(externalToggled.tickets[0].details, 'Concealed details');
assert.strictEqual(externalToggled.tickets[0].status, 'Resolved');
assert.strictEqual(externalTicket.status, 'Open');

const addedTicket = externalAdded.tickets[1];
const externalDeleted = ticketReducer(externalAdded, deleteTicket(4));
assert.strictEqual(externalDeleted.nextId, 6);
assert.notStrictEqual(externalDeleted.tickets, externalAdded.tickets);
assert.deepStrictEqual(externalDeleted.tickets, [addedTicket]);
assert.strictEqual(externalDeleted.tickets[0], addedTicket);

