'use strict';

function mapSafely(values, mapper, fallback) {
  if (!Array.isArray(values)) throw new TypeError('values must be an array');
  if (typeof mapper !== 'function') throw new TypeError('mapper must be a function');

  const output = new Array(values.length);
  const errors = [];

  for (let index = 0; index < values.length; index += 1) {
    const value = Object.prototype.hasOwnProperty.call(values, index)
      ? values[index]
      : undefined;
    try {
      output[index] = mapper(value, index);
    } catch (error) {
      errors.push({ index, error });
      output[index] = typeof fallback === 'function'
        ? fallback(error, index, value)
        : fallback;
    }
  }

  return { values: output, errors };
}

module.exports = { mapSafely };

