'use strict';
const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Reflect.ownKeys(api), ['mapSafely']);
const { mapSafely } = api;
assert.strictEqual(typeof mapSafely, 'function');

assert.deepStrictEqual(mapSafely([], x => x, 0), { values: [], errors: [] });

const input = [2, 3, 4];
const seen = [];
const normal = mapSafely(input, (value, index) => {
  seen.push([value, index]);
  return value * index;
}, null);
assert.deepStrictEqual(normal, { values: [0, 3, 8], errors: [] });
assert.deepStrictEqual(seen, [[2, 0], [3, 1], [4, 2]]);
assert.deepStrictEqual(input, [2, 3, 4]);

const localArrayPrototype = Object.create(Array.prototype);
Object.defineProperty(localArrayPrototype, '0', {
  value: 7,
  writable: true,
  enumerable: true,
  configurable: true
});
const sparse = new Array(3);
sparse[1] = 'present';
Object.setPrototypeOf(sparse, localArrayPrototype);
const sparseSeen = [];
const sparseFallbackCalls = [];
const sparseErrors = [new Error('hole zero'), new Error('hole two')];
const sparseResult = mapSafely(sparse, (value, index) => {
  sparseSeen.push([value, index]);
  if (index === 0) throw sparseErrors[0];
  if (index === 2) throw sparseErrors[1];
  return value;
}, (error, index, value) => {
  sparseFallbackCalls.push([error, index, value]);
  return `missing-${index}`;
});
assert.deepStrictEqual(sparseSeen, [[undefined, 0], ['present', 1], [undefined, 2]]);
assert.deepStrictEqual(sparseFallbackCalls, [
  [sparseErrors[0], 0, undefined],
  [sparseErrors[1], 2, undefined]
]);
assert.deepStrictEqual(sparseResult.values, ['missing-0', 'present', 'missing-2']);
assert.deepStrictEqual(sparseResult.errors, [
  { index: 0, error: sparseErrors[0] },
  { index: 2, error: sparseErrors[1] }
]);
assert.strictEqual(Object.prototype.hasOwnProperty.call(sparse, 0), false);
assert.strictEqual(Object.prototype.hasOwnProperty.call(sparse, 2), false);
assert.strictEqual(sparse[0], 7);

const firstError = new Error('first');
const secondError = { code: 'SECOND' };
const fallbackCalls = [];
const failed = mapSafely(['a', 'b', 'c'], (value, index) => {
  if (index === 0) throw firstError;
  if (index === 2) throw secondError;
  return value.toUpperCase();
}, (error, index, value) => {
  fallbackCalls.push([error, index, value]);
  return { recovered: index };
});
assert.deepStrictEqual(failed.values, [{ recovered: 0 }, 'B', { recovered: 2 }]);
assert.deepStrictEqual(failed.errors, [
  { index: 0, error: firstError },
  { index: 2, error: secondError }
]);
assert.deepStrictEqual(fallbackCalls, [
  [firstError, 0, 'a'],
  [secondError, 2, 'c']
]);
assert.strictEqual(failed.errors[0].error, firstError);

const sharedFallback = { safe: true };
const directFallback = mapSafely([1], () => { throw firstError; }, sharedFallback);
assert.strictEqual(directFallback.values[0], sharedFallback);

const callbackValue = { identity: true };
const identityResult = mapSafely([1], () => callbackValue, null);
assert.strictEqual(identityResult.values[0], callbackValue);

const fallbackFailure = new Error('fallback failed');
assert.throws(
  () => mapSafely([1, 2], () => { throw firstError; }, () => { throw fallbackFailure; }),
  error => error === fallbackFailure
);

for (const badValues of [null, {}, 'abc', 3, undefined]) {
  assert.throws(() => mapSafely(badValues, x => x, null), TypeError);
}
for (const badMapper of [null, {}, 'fn', 1, undefined]) {
  assert.throws(() => mapSafely([], badMapper, null), TypeError);
}

