'use strict';
const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Reflect.ownKeys(api).sort(), ['createEditorState', 'reduceEditor'].sort());
const { createEditorState, reduceEditor } = api;

const initial = createEditorState();
assert.deepStrictEqual(initial, {
  phase: 'idle',
  values: { name: '', description: '' },
  saved: { name: '', description: '' },
  error: null
});
const anotherInitial = createEditorState();
assert.notStrictEqual(anotherInitial, initial);
assert.notStrictEqual(anotherInitial.values, initial.values);
assert.notStrictEqual(anotherInitial.saved, initial.saved);
assert.notStrictEqual(initial.values, initial.saved);

function assertFresh(previous, next) {
  assert.notStrictEqual(next, previous);
  assert.notStrictEqual(next.values, previous.values);
  assert.notStrictEqual(next.saved, previous.saved);
  assert.notStrictEqual(next.values, next.saved);
}

const loading = reduceEditor(initial, { type: 'load-start' });
assertFresh(initial, loading);
assert.deepStrictEqual(loading, {
  phase: 'loading', values: { name: '', description: '' }, saved: { name: '', description: '' }, error: null
});

const profile = { name: 'Ada', description: 'Engineer' };
const loadAction = { type: 'load-success', profile };
const ready = reduceEditor(loading, loadAction);
assertFresh(loading, ready);
assert.deepStrictEqual(ready, {
  phase: 'ready',
  values: { name: 'Ada', description: 'Engineer' },
  saved: { name: 'Ada', description: 'Engineer' },
  error: null
});
profile.name = 'mutated later';
assert.strictEqual(ready.values.name, 'Ada');
assert.strictEqual(ready.saved.name, 'Ada');
assert.strictEqual(loadAction.profile.description, 'Engineer');

const editAction = { type: 'edit', field: 'description', value: 'Updated' };
const edited = reduceEditor(ready, editAction);
assertFresh(ready, edited);
assert.deepStrictEqual(edited.values, { name: 'Ada', description: 'Updated' });
assert.deepStrictEqual(edited.saved, { name: 'Ada', description: 'Engineer' });
assert.strictEqual(edited.phase, 'ready');
assert.strictEqual(edited.error, null);
assert.deepStrictEqual(editAction, { type: 'edit', field: 'description', value: 'Updated' });

const saving = reduceEditor(edited, { type: 'save-start' });
assertFresh(edited, saving);
assert.strictEqual(saving.phase, 'saving');
assert.strictEqual(saving.error, null);

const saved = reduceEditor(saving, { type: 'save-success' });
assertFresh(saving, saved);
assert.deepStrictEqual(saved.values, { name: 'Ada', description: 'Updated' });
assert.deepStrictEqual(saved.saved, { name: 'Ada', description: 'Updated' });
assert.strictEqual(saved.phase, 'ready');
assert.strictEqual(saved.error, null);

const blankName = reduceEditor(saved, { type: 'edit', field: 'name', value: '   ' });
const rejectedSave = reduceEditor(blankName, { type: 'save-start' });
assertFresh(blankName, rejectedSave);
assert.strictEqual(rejectedSave.phase, 'error');
assert.strictEqual(rejectedSave.error, 'Name required');
assert.strictEqual(rejectedSave.values.name, '   ');

const failure = reduceEditor(saved, { type: 'failure', message: 'Network unavailable' });
assertFresh(saved, failure);
assert.strictEqual(failure.phase, 'error');
assert.strictEqual(failure.error, 'Network unavailable');

const spacesFailureAction = { type: 'failure', message: '   ' };
const spacesFailure = reduceEditor(saved, spacesFailureAction);
assertFresh(saved, spacesFailure);
assert.strictEqual(spacesFailure.phase, 'error');
assert.strictEqual(spacesFailure.error, '   ');
assert.deepStrictEqual(spacesFailure.values, saved.values);
assert.deepStrictEqual(spacesFailure.saved, saved.saved);
assert.deepStrictEqual(spacesFailureAction, { type: 'failure', message: '   ' });

for (const bad of [null, undefined, [], 1, 'x']) {
  assert.throws(() => reduceEditor(bad, {}), error => error instanceof TypeError && error.message === 'Invalid editor input');
  assert.throws(() => reduceEditor(initial, bad), error => error instanceof TypeError && error.message === 'Invalid editor input');
}

