function createTaskDispatcher() {
  const items = [];
  let nextId = 1;
  const object = (value) => value !== null && typeof value === 'object' && !Array.isArray(value);
  const copy = (item) => ({ id: item.id, text: item.text });
  const notFound = () => ({ status: 404, body: { error: 'Not found' } });
  const textRequired = () => ({ status: 400, body: { error: 'Text required' } });

  return function dispatch(request) {
    if (!object(request) || typeof request.method !== 'string' || typeof request.path !== 'string') {
      return { status: 400, body: { error: 'Bad request' } };
    }

    if (request.method === 'GET' && request.path === '/items') {
      return { status: 200, body: items.map(copy) };
    }
    if (request.method === 'POST' && request.path === '/items') {
      if (!object(request.body) || typeof request.body.text !== 'string' || request.body.text.length === 0) {
        return textRequired();
      }
      const item = { id: `i${nextId}`, text: request.body.text };
      nextId += 1;
      items.push(item);
      return { status: 201, body: copy(item) };
    }

    const match = /^\/items\/([^/]+)$/.exec(request.path);
    if (!match) return notFound();
    const index = items.findIndex((item) => item.id === match[1]);
    if (index === -1) return notFound();

    if (request.method === 'PUT') {
      if (!object(request.body) || typeof request.body.text !== 'string' || request.body.text.length === 0) {
        return textRequired();
      }
      items[index] = { id: items[index].id, text: request.body.text };
      return { status: 200, body: copy(items[index]) };
    }
    if (request.method === 'DELETE') {
      items.splice(index, 1);
      return { status: 204, body: null };
    }
    return notFound();
  };
}

module.exports = { createTaskDispatcher };

