import { matchPath } from './solution';
import type { RouteSpec } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(message + ': expected ' + JSON.stringify(expected) + ', got ' + JSON.stringify(actual));
  }
}
function typeError(action: () => void, message: string): void {
  try {
    action();
  } catch (error) {
    if (error instanceof TypeError) return;
    throw new Error(message + ': wrong error type');
  }
  throw new Error(message + ': did not throw');
}

assert(matchPath([], '/anything') === null, 'empty route array returns null');
equal(matchPath([{ pattern: '/', destination: 'root' }], '/'), { destination: 'root', params: {} }, 'root matches root');
assert(matchPath([{ pattern: '/', destination: 'root' }], '/other') === null, 'root does not match a non-root path');

const routes: RouteSpec[] = [
  { pattern: '/shops/:shop/items/:item', destination: 'parameterized' },
  { pattern: '/shops/special/items/:item', destination: 'more-specific' },
  { pattern: '/:first/special/items/:item', destination: 'specific-tie-later' },
  { pattern: '*', destination: 'fallback-one' },
  { pattern: '*', destination: 'fallback-two' }
];
const originalOrder = routes.slice();
equal(matchPath(routes, '/shops/special/items/a%20b'), {
  destination: 'more-specific',
  params: { item: 'a%20b' }
}, 'greatest literal specificity wins and raw value is retained');
assert(routes.every((route, index) => route === originalOrder[index]), 'route array is not reordered or replaced');
equal(matchPath(routes, '/unknown'), { destination: 'fallback-one', params: {} }, 'first fallback is used when ordinary routes miss');

const tied: RouteSpec[] = [
  { pattern: '/a/:value', destination: 'first' },
  { pattern: '/:prefix/b', destination: 'second' }
];
equal(matchPath(tied, '/a/b'), { destination: 'first', params: { value: 'b' } }, 'declaration order breaks a specificity tie');
assert(matchPath([{ pattern: '/a/:x', destination: 'x' }], '/a') === null, 'segment counts must match');

const freshRoutes: RouteSpec[] = [{ pattern: '/users/:id', destination: 'user' }];
const matchOne = matchPath(freshRoutes, '/users/CaseSensitive');
const matchTwo = matchPath(freshRoutes, '/users/CaseSensitive');
if (matchOne === null || matchTwo === null) throw new Error('matching route not found');
assert(matchOne.params !== matchTwo.params, 'fresh params object returned each time');
(matchOne.params as Record<string, string>).id = 'mutated';
equal(matchTwo, { destination: 'user', params: { id: 'CaseSensitive' } }, 'returned params do not share mutable state');

const protoMatch = matchPath([{ pattern: '/:__proto__', destination: 'proto' }], '/value');
if (protoMatch === null) throw new Error('__proto__ route did not match');
assert(Object.prototype.hasOwnProperty.call(protoMatch.params, '__proto__'), '__proto__ is captured as an own property');
assert(protoMatch.params['__proto__'] === 'value', '__proto__ has the exact raw value');

const namedMatches = matchPath(
  [{ pattern: '/:constructor/:toString', destination: 'named' }],
  '/left/right'
);
if (namedMatches === null) throw new Error('constructor/toString route did not match');
assert(Object.prototype.hasOwnProperty.call(namedMatches.params, 'constructor'), 'constructor is an own parameter');
assert(Object.prototype.hasOwnProperty.call(namedMatches.params, 'toString'), 'toString is an own parameter');
assert(namedMatches.params['constructor'] === 'left', 'constructor parameter has exact value');
assert(namedMatches.params['toString'] === 'right', 'toString parameter has exact value');

for (const path of ['', 'relative', '/a//b', '/a?x=1', '/a#fragment']) {
  typeError(() => matchPath([], path), 'malformed path rejected: ' + path);
}
for (const pattern of ['', 'relative', '/a//b', '/a?x', '/a#x', '/:', '/:id/:id']) {
  typeError(
    () => matchPath([{ pattern, destination: 'bad' }], '/valid'),
    'malformed pattern rejected: ' + pattern
  );
}
typeError(() => matchPath([{ pattern: '/ok', destination: 'ok' }], 1 as unknown as string), 'non-string path rejected');

