      const patternPart = patternParts[i]!;
      const pathPart = pathParts[i]!;
      if (patternPart.startsWith(":")) setParam(params, patternPart.slice(1), pathPart);
      else if (patternPart === pathPart) score += 1;
      else return;
    }
    if (best === undefined || score > best.score) best = { route, params, score };
  });

  if (best !== undefined) {
    return { destination: best.route.destination, params: copyParams(best.params) };
