equal(decodeInlineNotes('plain text'), [{ type: 'text', text: 'plain text' }], 'plain text is returned');
equal(decodeInlineNotes('A {{note:remember}} B {{warning:careful}} C {{key:Enter}}.'), [
  { type: 'text', text: 'A ' },
  { type: 'note', text: 'remember' },
  { type: 'text', text: ' B ' },
  { type: 'warning', text: 'careful' },
  { type: 'text', text: ' C ' },
  { type: 'key', text: 'Enter' },
  { type: 'text', text: '.' }
], 'recognized markers preserve source order');
equal(decodeInlineNotes('{{route:Dashboard|/dash/main}}'), [
  { type: 'route', text: 'Dashboard', target: '/dash/main' }
], 'route marker is decoded');
equal(decodeInlineNotes('{{note:}}{{warning:}}{{key:}}{{route:|}}'), [
  { type: 'note', text: '' },
  { type: 'warning', text: '' },
  { type: 'key', text: '' },
  { type: 'route', text: '', target: '' }
], 'empty payloads and route fields are valid and adjacent markers stay separate');

equal(decodeInlineNotes('one\\ two\\{three\\} four\\\\five\\'), [
  { type: 'text', text: 'one two{three} four\\five\\' }
], 'outside escapes, doubled backslashes, and a trailing backslash are handled');
equal(decodeInlineNotes('{{note:a\\:b\\|c}}'), [
  { type: 'note', text: 'a:b|c' }
], 'escapes inside marker payload are removed once');
equal(decodeInlineNotes('{{route:left\\|side|target\\|part}}'), [
  { type: 'route', text: 'left|side', target: 'target|part' }
], 'first unescaped route separator is used');
equal(decodeInlineNotes('{{route:a|b|c}}'), [
  { type: 'route', text: 'a', target: 'b|c' }
], 'later unescaped separators belong to the target');

equal(decodeInlineNotes('x{{mystery:a\\}b}}y'), [
  { type: 'text', text: 'x{{mystery:a}b}}y' }
], 'unknown marker fallback is unescaped and coalesced as ordinary text');
equal(decodeInlineNotes('x{{route:left\\|right}}y'), [
  { type: 'text', text: 'x{{route:left|right}}y' }
], 'route without an unescaped separator stays text after unescaping');
equal(decodeInlineNotes('before {{note:a\\}b'), [
  { type: 'text', text: 'before {{note:a}b' }
], 'incomplete marker fallback is unescaped as ordinary text');
equal(decodeInlineNotes('\\{{note:not-a-marker}}'), [
  { type: 'text', text: '{{note:not-a-marker}}' }
], 'an escaped opening delimiter is not reinterpreted as a marker');
equal(decodeInlineNotes('\\\\{{key:X}}\\'), [
  { type: 'text', text: '\\' },
  { type: 'key', text: 'X' },
  { type: 'text', text: '\\' }
], 'doubled and trailing backslashes work next to a marker');
equal(decodeInlineNotes('{{note:outer {{warning:inner}} tail}}'), [
  { type: 'note', text: 'outer {{warning:inner' },
  { type: 'text', text: ' tail}}' }
], 'markers do not nest');

const first = decodeInlineNotes('{{note:first}}');
(first[0] as { type: 'note'; text: string }).text = 'mutated';
equal(decodeInlineNotes('{{note:first}}'), [{ type: 'note', text: 'first' }], 'calls retain no mutable state');

