import { PanelStateStore } from './solution';
import type { PanelSnapshot } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(message + ': expected ' + JSON.stringify(expected) + ', got ' + JSON.stringify(actual));
  }
}
function throwsTypeError(action: () => void, message: string): void {
  try {
    action();
  } catch (error) {
    if (error instanceof TypeError) return;
    throw new Error(message + ': wrong error type');
  }
  throw new Error(message + ': did not throw');
}

const empty = new PanelStateStore();
equal(empty.getSnapshot(), { map: false, metrics: false, notes: false }, 'omitted panels default to false');
const partial = new PanelStateStore({ metrics: true });
equal(partial.getSnapshot(), { map: false, metrics: true, notes: false }, 'partial initial state is applied');
throwsTypeError(
  () => new PanelStateStore({ map: 1 as unknown as boolean }),
  'explicit non-boolean is rejected'
);
throwsTypeError(
  () => new PanelStateStore({ notes: undefined } as unknown as Partial<Record<'map' | 'metrics' | 'notes', boolean>>),
  'explicit undefined is rejected'
);

const firstSnapshot = partial.getSnapshot();
const secondSnapshot = partial.getSnapshot();
assert(firstSnapshot !== secondSnapshot, 'getSnapshot allocates each time');
assert(Object.isFrozen(firstSnapshot) && Object.isFrozen(secondSnapshot), 'getSnapshot freezes snapshots');

const store = new PanelStateStore();
const calls: string[] = [];
const received: PanelSnapshot[] = [];
const listenerA = (snapshot: PanelSnapshot): void => {
  calls.push('A:' + String(snapshot.map));
  received.push(snapshot);
};
const listenerB = (snapshot: PanelSnapshot): void => {
  calls.push('B:' + String(snapshot.map));
  received.push(snapshot);
};
store.subscribe(listenerA);
store.subscribe(listenerB);
const unsubscribeLastA = store.subscribe(listenerA);
unsubscribeLastA();
unsubscribeLastA();

assert(calls.length === 0, 'subscribe is not immediate');
store.setVisible('map', true);
equal(calls, ['A:true', 'B:true'], 'duplicate registrations are independent and notify in order');
assert(received[0] !== received[1], 'each listener receives a distinct snapshot');
assert(Object.isFrozen(received[0]) && Object.isFrozen(received[1]), 'notification snapshots are frozen');
store.setVisible('map', true);
equal(calls.slice(-2), ['A:true', 'B:true'], 'repeating the current value still notifies');
store.toggle('notes');
equal(store.getSnapshot(), { map: true, metrics: false, notes: true }, 'toggle changes only the selected panel');
equal(calls.slice(-2), ['A:true', 'B:true'], 'toggle notifies active listeners in order');

const changing = new PanelStateStore();
const changedCalls: string[] = [];
let removeSecond: () => void = () => {};
let added = false;
changing.subscribe(snapshot => {
  changedCalls.push('first:' + String(snapshot.metrics));
  removeSecond();
  if (!added) {
    added = true;
    changing.subscribe(next => changedCalls.push('late:' + String(next.metrics)));
  }
});
removeSecond = changing.subscribe(snapshot => changedCalls.push('second:' + String(snapshot.metrics)));
changing.setVisible('metrics', true);
equal(changedCalls, ['first:true', 'second:true'], 'listener-list changes do not alter the current notification snapshot');
removeSecond();
removeSecond();
changing.toggle('metrics');
