import { FixedScaleVault } from './solution';
import type { BalanceListener } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) throw new Error(message + ': expected ' + String(expected) + ', got ' + String(actual));
}
function throwsAny(action: () => void, message: string): void {
  try {
    action();
  } catch {
    return;
  }
  throw new Error(message + ': did not throw');
}
function throwsKind(action: () => void, kind: 'TypeError' | 'RangeError', message: string): void {
  try {
    action();
  } catch (error) {
    if (kind === 'TypeError' ? error instanceof TypeError : error instanceof RangeError) return;
    throw new Error(message + ': wrong error type');
  }
  throw new Error(message + ': did not throw');
}

for (const decimals of [-1, 19, 1.5, Number.MAX_SAFE_INTEGER + 1, '2' as unknown as number]) {
  throwsAny(() => new FixedScaleVault(decimals, 'TOK'), 'invalid decimals rejected: ' + String(decimals));
}
throwsAny(() => new FixedScaleVault(2, '   \t'), 'whitespace-only symbol rejected');
throwsAny(() => new FixedScaleVault(2, 3 as unknown as string), 'non-string symbol rejected');

const zero = new FixedScaleVault(0, ' Z ');
equal(zero.getDecimals(), 0, 'zero decimals retained');
equal(zero.getSymbol(), ' Z ', 'valid symbol remains exact');
equal(zero.parseAmount('0'), 0n, 'zero parses');
equal(zero.parseAmount('123'), 123n, 'integer parses at zero scale');
equal(zero.formatAmount(123n), '123', 'zero-scale formatting');
throwsKind(() => zero.parseAmount('1.0'), 'RangeError', 'dot forbidden at zero scale');

const vault = new FixedScaleVault(3, 'USD');
equal(vault.getDecimals(), 3, 'decimals exposed');
equal(vault.getSymbol(), 'USD', 'symbol exposed');
equal(vault.parseAmount('0'), 0n, 'zero is padded');
equal(vault.parseAmount('1'), 1000n, 'whole amount is scaled');
equal(vault.parseAmount('1.2'), 1200n, 'fraction is padded on the right');
equal(vault.parseAmount('19.007'), 19007n, 'full precision parses');
equal(vault.formatAmount(0n), '0.000', 'formatted zero has fixed precision');
equal(vault.formatAmount(1200n), '1.200', 'formatted amount has exact precision');
equal(vault.formatAmount(7n), '0.007', 'sub-unit amount is formatted');

const malformed = ['', '00', '01', '+1', '-1', ' 1', '1 ', '1.', '.1', '1.2345', '1_000', '1e2', '1,0'];
for (const text of malformed) {
  throwsKind(() => vault.parseAmount(text), 'RangeError', 'malformed amount rejected: ' + text);
}
for (const text of ['1\n', '1\r', '1\r\n', '1\u2028', '1\u2029']) {
  throwsKind(() => zero.parseAmount(text), 'RangeError', 'zero-scale terminal line character rejected');
  throwsKind(() => vault.parseAmount(text), 'RangeError', 'scaled terminal line character rejected');
}
throwsKind(() => vault.parseAmount(1 as unknown as string), 'TypeError', 'non-string parse input rejected');
throwsAny(() => vault.formatAmount(-1n), 'negative format input rejected');
throwsAny(() => vault.formatAmount(1 as unknown as bigint), 'non-bigint format input rejected');

for (const account of ['', ' \n\t']) {
  throwsAny(() => vault.getBalance(account), 'blank account rejected');
}
throwsAny(() => vault.getBalance(1 as unknown as string), 'non-string account rejected');
equal(vault.getBalance('Alice'), 0n, 'unknown balance is zero');
equal(vault.allowance('Owner', 'Spender'), 0n, 'unknown allowance is zero');

const calls: string[] = [];
const listenerA: BalanceListener = balance => calls.push('A:' + balance.toString());
const listenerB: BalanceListener = balance => calls.push('B:' + balance.toString());
vault.subscribe('Alice', listenerA);
vault.subscribe('Alice', listenerB);
const unsubscribeLastA = vault.subscribe('Alice', listenerA);
calls.length = 0;
unsubscribeLastA();
unsubscribeLastA();
vault.setBalance('Alice', 5n);
equal(calls.join(','), 'A:5,B:5', 'duplicate registrations are independent and emit in order');
vault.setBalance('Alice', 5n);
equal(calls.length, 2, 'duplicate assignment emits nothing');
vault.setBalance('Alice', 6n);
equal(calls.slice(-2).join(','), 'A:6,B:6', 'later balance change emits in order');
equal(vault.getBalance('Alice'), 6n, 'balance stored');
assert(vault.getBalance('alice') === 0n, 'account identifiers are case-sensitive');
throwsAny(() => vault.setBalance('Alice', -1n), 'negative balance rejected');
throwsAny(() => vault.setBalance('Alice', 1 as unknown as bigint), 'non-bigint balance rejected');

const snapshotVault = new FixedScaleVault(0, 'S');
const snapshotCalls: string[] = [];
let removeSecond: () => void = () => {};
let added = false;
snapshotVault.subscribe('a', value => {
  if (value === 0n) return;
  snapshotCalls.push('first:' + value.toString());
  removeSecond();
  if (!added) {
    added = true;
    snapshotVault.subscribe('a', next => snapshotCalls.push('late:' + next.toString()));
  }
});
removeSecond = snapshotVault.subscribe('a', value => {
  if (value !== 0n) snapshotCalls.push('second:' + value.toString());
});
snapshotVault.setBalance('a', 1n);
equal(snapshotCalls.join(','), 'first:1,late:1,second:1', 'emission snapshots listeners while nested subscription remains immediately observable');
removeSecond();
removeSecond();
snapshotVault.setBalance('a', 2n);
equal(snapshotCalls.slice(-2).join(','), 'first:2,late:2', 'subscription changes affect later emissions');

vault.approve('Owner', 'Spender', 9n);
equal(vault.allowance('Owner', 'Spender'), 9n, 'allowance stored');
equal(vault.allowance('owner', 'Spender'), 0n, 'allowance identifiers are case-sensitive');
throwsAny(() => vault.approve('Owner', 'Spender', -1n), 'negative allowance rejected');
throwsAny(() => vault.approve('Owner', 'Spender', 1 as unknown as bigint), 'non-bigint allowance rejected');
throwsAny(() => vault.approve(' ', 'Spender', 1n), 'blank allowance owner rejected');
throwsAny(() => vault.allowance('Owner', '\t'), 'blank allowance spender rejected');

const throwing = new FixedScaleVault(0, 'T');
const delivery: string[] = [];
throwing.subscribe('a', value => {
  if (value !== 0n) {
    delivery.push('first');
    throw new Error('listener');
  }
});
throwing.subscribe('a', value => { if (value !== 0n) delivery.push('second'); });
let propagated = false;
try {
  throwing.setBalance('a', 1n);
} catch (error) {
  propagated = error instanceof Error && error.message === 'listener';
}
assert(propagated, 'listener exception propagates');
equal(delivery.join(','), 'first', 'listener exception stops delivery');
equal(throwing.getBalance('a'), 1n, 'balance mutation survives listener exception');

