import { ReleaseTimeline } from './solution';
import type { TimelineEvent, TimelineListener } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(message + ': expected ' + JSON.stringify(expected) + ', got ' + JSON.stringify(actual));
  }
}
function throwsAny(action: () => void, message: string): void {
  try {
    action();
  } catch {
    return;
  }
  throw new Error(message + ': did not throw');
}
function rangeError(action: () => void, message: string): void {
  try {
    action();
  } catch (error) {
    if (error instanceof RangeError) return;
    throw new Error(message + ': wrong error type');
  }
  throw new Error(message + ': did not throw');
}

const timeline = new ReleaseTimeline();
equal(timeline.snapshot(), [], 'initial timeline is empty');

const calls: string[] = [];
const received: TimelineEvent[] = [];
let removeB: () => void = () => {};
const listenerA: TimelineListener = event => {
  calls.push('A:' + event.kind + ':' + String(event.entry.id));
  received.push(event);
  removeB();
};
const listenerB: TimelineListener = event => {
  calls.push('B:' + event.kind + ':' + String(event.entry.id));
  received.push(event);
};
timeline.subscribe(listenerA);
removeB = timeline.subscribe(listenerB);
const unsubscribeLastA = timeline.subscribe(listenerA);
unsubscribeLastA();
unsubscribeLastA();

const first = timeline.append('  One  ');
equal(first, { id: 1, label: 'One', note: null }, 'append trims label and defaults note');
equal(calls, ['A:added:1', 'B:added:1'], 'duplicate registrations are independent and removal does not alter current delivery');
received[0].entry.label = 'event mutation';
first.label = 'return mutation';
equal(timeline.snapshot(), [{ id: 1, label: 'One', note: null }], 'events and returned entries cannot mutate state');
removeB();
removeB();

const second = timeline.append('Two', ' unchanged note ');
equal(second, { id: 2, label: 'Two', note: ' unchanged note ' }, 'supplied note remains unchanged');
equal(calls.slice(-1), ['A:added:2'], 'unsubscription affects later events and is idempotent');
const renamed = timeline.rename(2, '  Second  ');
equal(renamed, { id: 2, label: 'Second', note: ' unchanged note ' }, 'rename trims label and preserves note');
renamed.note = 'changed';
equal(timeline.snapshot()[1], { id: 2, label: 'Second', note: ' unchanged note ' }, 'rename result is copied');

const promoted = timeline.promote(2);
equal(promoted, { id: 2, label: 'Second', note: ' unchanged note ' }, 'promote returns a copy');
equal(timeline.snapshot(), [
  { id: 2, label: 'Second', note: ' unchanged note ' },
  { id: 1, label: 'One', note: null }
], 'promotion moves the entry to the front and preserves other order');
timeline.promote(2);
equal(timeline.snapshot().map(entry => entry.id), [2, 1], 'promoting the first entry still succeeds');

const snap = timeline.snapshot();
snap[0].label = 'mutated';
snap.reverse();
equal(timeline.snapshot().map(entry => entry.label), ['Second', 'One'], 'snapshot array and entries are copies');
assert(timeline.remove(99) === false, 'missing valid ID removal returns false');
assert(timeline.remove(2) === true, 'existing entry is removed');
equal(timeline.snapshot(), [{ id: 1, label: 'One', note: null }], 'remove updates the timeline');
const third = timeline.append('Three');
assert(third.id === 3, 'removed IDs are never reused');

throwsAny(() => timeline.append('   '), 'blank append label rejected');
throwsAny(() => timeline.append('Valid', 3 as unknown as string), 'non-string note rejected');
throwsAny(() => timeline.rename(3, ''), 'blank rename label rejected');
for (const id of [0, -1, 1.5, Number.NaN]) {
  rangeError(() => timeline.rename(id, 'x'), 'malformed rename ID rejected');
  rangeError(() => timeline.remove(id), 'malformed remove ID rejected');
  rangeError(() => timeline.promote(id), 'malformed promote ID rejected');
}
rangeError(() => timeline.rename(999, 'x'), 'missing rename ID rejected');
rangeError(() => timeline.promote(999), 'missing promote ID rejected');

const beforeFailedCalls = calls.length;
assert(timeline.remove(999) === false, 'missing removal remains false');
assert(calls.length === beforeFailedCalls, 'failed operations emit nothing');

const throwing = new ReleaseTimeline();
const delivered: string[] = [];
throwing.subscribe(() => { delivered.push('first'); throw new Error('boom'); });
throwing.subscribe(() => delivered.push('second'));
let propagated = false;
try {
  throwing.append('Committed');
} catch (error) {
  propagated = error instanceof Error && error.message === 'boom';
}
assert(propagated, 'listener exception propagates');
equal(delivered, ['first'], 'listener exception stops later delivery');
equal(throwing.snapshot(), [{ id: 1, label: 'Committed', note: null }], 'mutation completes before listener exception');

prompt.text:
Implement an observable ordered release timeline in one complete TypeScript file. Export:

```typescript
export type ReleaseEntry = { id: number; label: string; note: string | null };
export type TimelineEvent =
  | { kind: "added"; entry: ReleaseEntry }
  | { kind: "renamed"; entry: ReleaseEntry }
  | { kind: "removed"; entry: ReleaseEntry }
  | { kind: "promoted"; entry: ReleaseEntry };
export type TimelineListener = (event: TimelineEvent) => void;

export class ReleaseTimeline {
  subscribe(listener: TimelineListener): () => void;
  append(label: string, note?: string): ReleaseEntry;
  rename(id: number, label: string): ReleaseEntry;
  remove(id: number): boolean;
  promote(id: number): ReleaseEntry;
  snapshot(): ReleaseEntry[];
}
```

Labels must be non-empty after trimming and are stored trimmed. Notes default to `null`; supplied notes must be strings and are stored unchanged. IDs start at 1 and are never reused. `rename`, `remove`, and `promote` require a positive integer ID; malformed IDs throw `RangeError`. `rename` and `promote` throw `RangeError` when the ID is absent, while `remove` returns `false`. Promotion moves an entry to the front while preserving the relative order of all others; promoting the first entry is still successful.

Listeners run synchronously in subscription order after a successful mutation. The returned unsubscribe function is idempotent. A listener removed during notification must not affect the current notification, only later ones. Listener exceptions propagate after the mutation and stop delivery of that event to later listeners. Events, returned entries, and snapshots must contain copies, so callers cannot mutate internal state. Failed operations emit nothing.

Return only the complete source file; do not include Markdown fences or prose.

